import data from "./localities.json";
import { canonicalCounty } from "./ro-counties";
import { matchLocality, type LocalityMatch, type UrbanKind } from "./match";

// Server side: the localities of a county, from the official SIRUTA list
// (generated by scripts/build-localities.mjs).
const counties = data.counties as Record<string, string[]>;
const urban = data.urban as Record<string, Record<string, UrbanKind>>;

export function getLocalities(county: string): string[] {
  const official = canonicalCounty(county);
  return official ? (counties[official] ?? []) : [];
}

// Every city, town and municipality of the county with its kind (county seat,
// municipality, town; Bucharest: sector), so they can be listed first.
export function getUrban(county: string): Record<string, UrbanKind> {
  const official = canonicalCounty(county);
  return official ? (urban[official] ?? {}) : {};
}

export function checkLocality(county: string, input: string): LocalityMatch {
  return matchLocality(getLocalities(county), input);
}
